// Apple Root CA - G3, DER-encoded, base64 here so it ships inside the
// compiled JS (no static-asset copy step needed in the build/Docker
// pipeline, which only carries dist/, prisma/, proto/ and scripts/ into the
// final image — a loose file under src/ would silently go missing).
//
// Source: https://www.apple.com/certificateauthority/AppleRootCA-G3.cer
// Subject: CN=Apple Root CA - G3, O=Apple Inc., C=US
// Valid: 2014-04-30 .. 2039-04-30
//
// This is Apple's PUBLIC root certificate, not a secret — same as any TLS
// root-CA bundle. Required by @apple/app-store-server-library's
// SignedDataVerifier to validate the certificate chain on every signed
// transaction/notification it decodes.
const APPLE_ROOT_CA_G3_BASE64 =
  "";

export function getAppleRootCertificates(): Buffer[] {
  return [Buffer.from(APPLE_ROOT_CA_G3_BASE64, "base64")];
}
